import { bit, integer, ipv4, Malformed, type Dissection, type Fields } from './link_network.ts';

const typeNames = new Map([
  [1, 'A'],
  [2, 'NS'],
  [5, 'CNAME'],
  [6, 'SOA'],
  [12, 'PTR'],
  [15, 'MX'],
  [16, 'TXT'],
  [28, 'AAAA'],
]);
export const typeName = (type: number) => typeNames.get(type) ?? `TYPE${type}`;
export const rcodeName = (rcode: number) =>
  ['NoError', 'FormErr', 'ServFail', 'NXDomain', 'NotImp', 'Refused'][rcode] ?? `RCODE${rcode}`;
export interface DnsAnswer {
  type: number;
  data: string;
}
export interface DnsDissection extends Dissection {
  answers: DnsAnswer[];
}
function ipv6(bytes: number[]): string {
  const groups = Array.from({ length: 8 }, (_, i) => integer(bytes, i * 2, 2));
  let bestStart = -1;
  let bestLength = 1;
  for (let i = 0; i < 8;) {
    if (groups[i] !== 0) {
      i++;
      continue;
    }
    const start = i;
    while (i < 8 && groups[i] === 0) i++;
    if (i - start > bestLength) {
      bestStart = start;
      bestLength = i - start;
    }
  }
  const text = groups.map((group) => group.toString(16));
  return bestStart < 0
    ? text.join(':')
    : text.slice(0, bestStart).join(':') + '::' + text.slice(bestStart + bestLength).join(':');
}
export function dns(bytes: number[]): DnsDissection {
  const requireBytes = (position: number, length: number) => {
    if (position + length > bytes.length) throw new Malformed('dns: truncated');
  };
  const read = (position: number, length: number) => {
    requireBytes(position, length);
    return integer(bytes, position, length);
  };
  const name = (start: number): { text: string; end: number } => {
    let position = start;
    let pointers = 0;
    let end: number | undefined;
    const labels: string[] = [];
    while (true) {
      const c = read(position, 1);
      if (c === 0) return { text: labels.join('.') || '<root>', end: end ?? position + 1 };
      if (c >= 192) {
        const d = read(position + 1, 1);
        end ??= position + 2;
        if (++pointers > 16) throw new Malformed('dns: compression loop');
        position = (c - 192) * 256 + d;
        if (position >= bytes.length) throw new Malformed('dns: pointer out of range');
      } else if (c >= 64) throw new Malformed('dns: bad label type');
      else {
        requireBytes(position + 1, c);
        labels.push(
          bytes
            .slice(position + 1, position + c + 1)
            .map((byte) =>
              byte >= 33 && byte <= 126 && byte !== 46 && byte !== 92
                ? String.fromCharCode(byte)
                : '\\' + String(byte).padStart(3, '0'),
            )
            .join(''),
        );
        position += c + 1;
      }
    }
  };
  requireBytes(0, 12);
  const flags = read(2, 2);
  const counts = [read(4, 2), read(6, 2), read(8, 2), read(10, 2)];
  const fields: Fields = new Map([
    ['dns.id', [read(0, 2)]],
    ['dns.flags', [flags]],
    ['dns.flags.response', [bit(flags, 15)]],
    ['dns.flags.opcode', [Math.floor(flags / 2048) % 16]],
    ['dns.flags.rcode', [flags % 16]],
    ['dns.count.queries', [counts[0]]],
    ['dns.count.answers', [counts[1]]],
    ['dns.count.auth_rr', [counts[2]]],
    ['dns.count.add_rr', [counts[3]]],
  ]);
  const append = (field: string, value: string | number) => {
    const values = fields.get(field) ?? [];
    values.push(value);
    fields.set(field, values);
  };
  let position = 12;
  for (let i = 0; i < counts[0]; i++) {
    const question = name(position);
    position = question.end;
    requireBytes(position, 4);
    append('dns.qry.name', question.text);
    append('dns.qry.type', read(position, 2));
    position += 4;
  }
  const answers: DnsAnswer[] = [];
  for (let section = 1; section <= 3; section++) {
    for (let i = 0; i < counts[section]; i++) {
      const owner = name(position);
      position = owner.end;
      requireBytes(position, 10);
      const type = read(position, 2);
      const rrClass = read(position + 2, 2);
      const ttl = read(position + 4, 4);
      const length = read(position + 8, 2);
      const start = position + 10;
      requireBytes(start, length);
      let data: string;
      let end: number;
      if (type === 1) {
        data = ipv4(read(start, 4));
        end = start + 4;
      } else if (type === 28) {
        requireBytes(start, 16);
        data = ipv6(bytes.slice(start, start + 16));
        end = start + 16;
      } else if ([2, 5, 12].includes(type)) {
        const result = name(start);
        data = result.text;
        end = result.end;
      } else if (type === 15) {
        const preference = read(start, 2);
        const result = name(start + 2);
        data = `${preference} ${result.text}`;
        end = result.end;
      } else if (type === 6) {
        const first = name(start);
        const second = name(first.end);
        const values: number[] = [];
        for (let j = 0; j < 5; j++) values.push(read(second.end + j * 4, 4));
        data = `${first.text} ${second.text} ${values.join(' ')}`;
        end = second.end + 20;
      } else {
        data = `${length} bytes`;
        end = start + length;
      }
      if (end !== start + length) throw new Malformed('dns: bad rdata length');
      append(
        ['', 'dns.answer', 'dns.authority', 'dns.additional'][section],
        `${owner.text} ${typeName(type)} ${rrClass === 1 ? 'IN' : `CLASS${rrClass}`} ${ttl} ${data}`,
      );
      if (section === 1) {
        answers.push({ type, data });
        if (type === 1) append('dns.a', read(start, 4));
      }
      position = start + length;
    }
  }
  return { fields, payload: [], answers };
}

import type { Packet } from './main.ts';
import { ipv4, numberField, numeric } from './link_network.ts';

export type Mark = 'retransmission' | 'out_of_order' | 'lost_segment' | 'duplicate_ack';
export const marks: Mark[] = ['retransmission', 'out_of_order', 'lost_segment', 'duplicate_ack'];
export type SideName = 'client' | 'server';
interface Endpoint {
  address: number;
  port?: number;
}
interface Side {
  endpoint: Endpoint;
  isn?: number;
  mss?: number;
  wscale?: number;
  base?: number;
  expected?: number;
  advanced: number;
  intervals: Set<string>;
  previousAck?: { ack: number; window: number; packet: number; count: number };
  packets: number;
  payload: number;
  counts: Record<Mark, number>;
}
type State =
  'SYN_SENT' | 'SYN_RECEIVED' | 'ESTABLISHED' | 'FIN_WAIT' | 'CLOSING' | 'CLOSED' | 'RESET';
export interface Stream {
  number: number;
  client: Side;
  server: Side;
  state: State;
  history: { state: State; packet: number }[];
  start: number;
  end: number;
  packets: number;
  bytes: number;
  syn?: number;
  synAck?: number;
  ack?: number;
  events: { packet: number; side: SideName; mark: Mark; seq: number; length: number }[];
  firstClose?: SideName;
  secondFin?: number;
}
const endpointKey = (endpoint: Endpoint) => `${endpoint.address}:${endpoint.port ?? '-'}`;
const pairKey = (a: Endpoint, b: Endpoint) => [endpointKey(a), endpointKey(b)].sort().join('|');
export const endpointNotation = (endpoint: Endpoint) =>
  ipv4(endpoint.address) + (endpoint.port === undefined ? '' : ':' + endpoint.port);
const mod32 = (value: number) => (value + 4294967296) % 4294967296;
function side(endpoint: Endpoint): Side {
  return {
    endpoint,
    advanced: 0,
    intervals: new Set(),
    packets: 0,
    payload: 0,
    counts: { retransmission: 0, out_of_order: 0, lost_segment: 0, duplicate_ack: 0 },
  };
}
export function trackTcp(packets: Packet[]): Stream[] {
  const streams: Stream[] = [];
  const latest = new Map<string, Stream>();
  for (const packet of packets) {
    const f = packet.fields;
    if (!f.has('tcp.srcport')) continue;
    const source = { address: numeric(f, 'ip.src'), port: numeric(f, 'tcp.srcport') };
    const destination = { address: numeric(f, 'ip.dst'), port: numeric(f, 'tcp.dstport') };
    const seq = numeric(f, 'tcp.seq_raw');
    const ack = numberField(f, 'tcp.ack_raw');
    const window = numeric(f, 'tcp.window');
    const payload = numeric(f, 'tcp.len');
    const syn = numeric(f, 'tcp.flags.syn') === 1;
    const fin = numeric(f, 'tcp.flags.fin') === 1;
    const rst = numeric(f, 'tcp.flags.rst') === 1;
    const hasAck = ack !== undefined;
    const key = pairKey(source, destination);
    let stream = latest.get(key);
    const recordSyn = (target: Stream, name: SideName) => {
      const s = target[name];
      s.isn = seq;
      s.mss = numberField(f, 'tcp.options.mss');
      s.wscale = numberField(f, 'tcp.options.wscale');
      if (name === 'client') target.syn = packet.number;
      else target.synAck = packet.number;
    };
    if (!stream || ((stream.state === 'CLOSED' || stream.state === 'RESET') && syn && !hasAck)) {
      const state: State = syn ? (hasAck ? 'SYN_RECEIVED' : 'SYN_SENT') : 'ESTABLISHED';
      stream = {
        number: streams.length,
        client: side(syn && hasAck ? destination : source),
        server: side(syn && hasAck ? source : destination),
        state,
        history: [{ state, packet: packet.number }],
        start: packet.time,
        end: packet.time,
        packets: 0,
        bytes: 0,
        events: [],
      };
      if (syn) recordSyn(stream, hasAck ? 'server' : 'client');
      streams.push(stream);
      latest.set(key, stream);
    }
    f.set('tcp.stream', [stream.number]);
    const name: SideName =
      endpointKey(source) === endpointKey(stream.client.endpoint) ? 'client' : 'server';
    const thisSide = stream[name];
    const other = stream[name === 'client' ? 'server' : 'client'];
    thisSide.base ??= seq;
    if (hasAck) other.base ??= ack;
    const relative = mod32(seq - thisSide.base);
    f.set('tcp.seq', [relative]);
    if (ack !== undefined && other.base !== undefined) f.set('tcp.ack', [mod32(ack - other.base)]);
    const length = payload + (syn ? 1 : 0) + (fin ? 1 : 0);
    let mark: Mark | undefined;
    if (length > 0) {
      const expected = thisSide.expected;
      if (expected !== undefined && relative > expected) mark = 'lost_segment';
      else if (expected !== undefined && relative < expected) {
        mark = thisSide.intervals.has(`${relative},${length}`)
          ? 'retransmission'
          : packet.time - thisSide.advanced < 3000
            ? 'out_of_order'
            : 'retransmission';
      }
      thisSide.intervals.add(`${relative},${length}`);
      if (expected === undefined || relative + length > expected) {
        thisSide.expected = relative + length;
        thisSide.advanced = packet.time;
      }
    } else if (ack !== undefined && !rst) {
      const previous = thisSide.previousAck;
      if (previous && ack === previous.ack && window === previous.window) {
        mark = 'duplicate_ack';
        previous.count++;
        packet.duplicateAck = { original: previous.packet, count: previous.count };
      }
    }
    if (ack !== undefined && mark !== 'duplicate_ack') {
      thisSide.previousAck = { ack, window, packet: packet.number, count: 0 };
    }
    if (mark) {
      f.set(`tcp.analysis.${mark}`, [true]);
      thisSide.counts[mark]++;
      stream.events.push({ packet: packet.number, side: name, mark, seq: relative, length });
    }
    f.set('tcp.window.calc', [
      stream.client.wscale !== undefined && stream.server.wscale !== undefined && !syn
        ? window * 2 ** (thisSide.wscale ?? 0)
        : window,
    ]);
    let state = stream.state;
    if (rst) {
      if (state !== 'CLOSED' && state !== 'RESET') state = 'RESET';
    } else if (
      state === 'SYN_SENT' &&
      name === 'server' &&
      syn &&
      ack !== undefined &&
      stream.client.isn !== undefined &&
      ack === mod32(stream.client.isn + 1)
    ) {
      state = 'SYN_RECEIVED';
      recordSyn(stream, 'server');
    } else if (
      state === 'SYN_RECEIVED' &&
      name === 'client' &&
      !syn &&
      ack !== undefined &&
      stream.server.isn !== undefined &&
      ack === mod32(stream.server.isn + 1)
    ) {
      state = 'ESTABLISHED';
      stream.ack = packet.number;
    } else if (state === 'ESTABLISHED' && fin) {
      state = 'FIN_WAIT';
      stream.firstClose = name;
    } else if (state === 'FIN_WAIT' && fin && name !== stream.firstClose) {
      state = 'CLOSING';
      stream.secondFin = mod32(seq + payload + 1);
    } else if (
      state === 'CLOSING' &&
      name === stream.firstClose &&
      ack !== undefined &&
      ack === stream.secondFin
    ) {
      state = 'CLOSED';
    }
    if (state !== stream.state) {
      stream.state = state;
      stream.history.push({ state, packet: packet.number });
    }
    thisSide.packets++;
    thisSide.payload += payload;
    stream.packets++;
    stream.bytes += packet.length;
    stream.end = packet.time;
  }
  return streams;
}
export interface Conversation {
  kind: 'ipv4' | 'tcp' | 'udp';
  a: Endpoint;
  b: Endpoint;
  first: number;
  start: number;
  end: number;
  packetsAB: number;
  bytesAB: number;
  packetsBA: number;
  bytesBA: number;
}
export interface EndpointTotals {
  address: number;
  txPackets: number;
  txBytes: number;
  rxPackets: number;
  rxBytes: number;
}
export function aggregate(packets: Packet[]): {
  conversations: Conversation[];
  endpoints: EndpointTotals[];
} {
  const conversations = new Map<string, Conversation>();
  const endpoints = new Map<number, EndpointTotals>();
  for (const packet of packets) {
    const f = packet.fields;
    if (!f.has('ip.src')) continue;
    const src = numeric(f, 'ip.src');
    const dst = numeric(f, 'ip.dst');
    for (const [address, sent] of [
      [src, true],
      [dst, false],
    ] as const) {
      const totals = endpoints.get(address) ?? {
        address,
        txPackets: 0,
        txBytes: 0,
        rxPackets: 0,
        rxBytes: 0,
      };
      if (sent) {
        totals.txPackets++;
        totals.txBytes += packet.length;
      } else {
        totals.rxPackets++;
        totals.rxBytes += packet.length;
      }
      endpoints.set(address, totals);
    }
    const add = (
      kind: Conversation['kind'],
      source: Endpoint,
      destination: Endpoint,
      identity: string,
    ) => {
      const key = kind + ':' + identity;
      let conversation = conversations.get(key);
      if (!conversation) {
        conversation = {
          kind,
          a: source,
          b: destination,
          first: packet.number,
          start: packet.time,
          end: packet.time,
          packetsAB: 0,
          bytesAB: 0,
          packetsBA: 0,
          bytesBA: 0,
        };
        conversations.set(key, conversation);
      }
      if (endpointKey(source) === endpointKey(conversation.a)) {
        conversation.packetsAB++;
        conversation.bytesAB += packet.length;
      } else {
        conversation.packetsBA++;
        conversation.bytesBA += packet.length;
      }
      conversation.end = packet.time;
    };
    const source = { address: src };
    const destination = { address: dst };
    add('ipv4', source, destination, pairKey(source, destination));
    if (f.has('tcp.stream')) {
      add(
        'tcp',
        { address: src, port: numeric(f, 'tcp.srcport') },
        { address: dst, port: numeric(f, 'tcp.dstport') },
        String(numeric(f, 'tcp.stream')),
      );
    }
    if (f.has('udp.srcport')) {
      const a = { address: src, port: numeric(f, 'udp.srcport') };
      const b = { address: dst, port: numeric(f, 'udp.dstport') };
      add('udp', a, b, pairKey(a, b));
    }
  }
  const kindOrder = { ipv4: 0, tcp: 1, udp: 2 };
  return {
    conversations: [...conversations.values()].sort(
      (a, b) =>
        b.bytesAB + b.bytesBA - a.bytesAB - a.bytesBA ||
        b.packetsAB + b.packetsBA - a.packetsAB - a.packetsBA ||
        kindOrder[a.kind] - kindOrder[b.kind] ||
        a.first - b.first,
    ),
    endpoints: [...endpoints.values()].sort(
      (a, b) =>
        b.txBytes + b.rxBytes - a.txBytes - a.rxBytes ||
        b.txPackets + b.rxPackets - a.txPackets - a.rxPackets ||
        a.address - b.address,
    ),
  };
}

import { readFileSync } from 'node:fs';

export interface Capture {
  number: number;
  time: number;
  length: number;
  bytes: number[];
  error?: string;
}
export function readCapture(): Capture[] {
  const packets: Capture[] = [];
  let current: Capture | undefined;
  const finish = () => {
    if (current && !current.error && current.bytes.length !== current.length) {
      current.error = `dump: length mismatch (header ${current.length}, data ${current.bytes.length})`;
    }
  };
  readFileSync('input/capture.txt', 'ascii')
    .slice(0, -1)
    .split('\n')
    .forEach((line, i) => {
      if (line.startsWith('PACKET ')) {
        finish();
        const parts = line.split(' ');
        current = { number: +parts[1], time: +parts[2], length: +parts[3], bytes: [] };
        packets.push(current);
      } else if (line && current && !current.error) {
        if (!/^[0-9a-f]{4}  [0-9a-f]{2}( [0-9a-f]{2}){0,15}$/.test(line)) {
          current.error = `dump: bad line ${i + 1}`;
        } else if (parseInt(line.slice(0, 4), 16) !== current.bytes.length) {
          current.error = `dump: offset mismatch at line ${i + 1}`;
        } else {
          current.bytes.push(
            ...line
              .slice(6)
              .split(' ')
              .map((byte) => parseInt(byte, 16)),
          );
        }
      }
    });
  finish();
  return packets;
}
export function dumpLines(bytes: number[]): string[] {
  const lines: string[] = [];
  for (let offset = 0; offset < bytes.length; offset += 16) {
    const piece = bytes.slice(offset, offset + 16);
    const hex = piece
      .map((byte) => byte.toString(16).padStart(2, '0'))
      .join(' ')
      .padEnd(47);
    const characters = piece
      .map((byte) => (byte >= 32 && byte <= 126 ? String.fromCharCode(byte) : '.'))
      .join('');
    lines.push(`${offset.toString(16).padStart(4, '0')}  ${hex}  |${characters}|`);
  }
  return lines;
}

export type FieldValue = number | string | true;
export type Fields = Map<string, FieldValue[]>;
export interface Dissection {
  fields: Fields;
  payload: number[];
}
export class Malformed extends Error {}
export function integer(bytes: number[], offset: number, count: number): number {
  let value = 0;
  for (let i = offset; i < offset + count; i++) value = value * 256 + bytes[i];
  return value;
}
export function numberField(fields: Fields, name: string): number | undefined {
  const value = fields.get(name)?.[0];
  return typeof value === 'number' ? value : undefined;
}
export function numeric(fields: Fields, name: string): number {
  const value = numberField(fields, name);
  if (value === undefined) throw new Error(`Missing numeric field ${name}`);
  return value;
}
export function stringField(fields: Fields, name: string): string | undefined {
  const value = fields.get(name)?.[0];
  return typeof value === 'string' ? value : undefined;
}
export const bit = (value: number, position: number) => Math.floor(value / 2 ** position) % 2;
export function checksum(bytes: number[]): string {
  let sum = 0;
  for (let i = 0; i < bytes.length; i += 2) sum += bytes[i] * 256 + (bytes[i + 1] ?? 0);
  while (sum > 65535) sum = (sum % 65536) + Math.floor(sum / 65536);
  return sum === 65535 ? 'good' : 'bad';
}
export const hex = (value: number, digits: number) =>
  '0x' + value.toString(16).padStart(digits, '0');
export function addressBytes(value: number, count: number): number[] {
  return Array.from({ length: count }, (_, i) => Math.floor(value / 256 ** (count - i - 1)) % 256);
}
export const ipv4 = (value: number) => addressBytes(value, 4).join('.');
export const mac = (value: number) =>
  addressBytes(value, 6)
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join(':');
export function ethernet(bytes: number[]): Dissection {
  if (bytes.length < 14) throw new Malformed('eth: truncated');
  return {
    fields: new Map([
      ['eth.dst', [integer(bytes, 0, 6)]],
      ['eth.src', [integer(bytes, 6, 6)]],
      ['eth.type', [integer(bytes, 12, 2)]],
    ]),
    payload: bytes.slice(14),
  };
}
export function arp(bytes: number[]): Dissection {
  if (bytes.length < 28) throw new Malformed('arp: truncated');
  if (
    integer(bytes, 0, 2) !== 1 ||
    integer(bytes, 2, 2) !== 2048 ||
    bytes[4] !== 6 ||
    bytes[5] !== 4
  ) {
    throw new Malformed('arp: unsupported format');
  }
  return {
    fields: new Map([
      ['arp.opcode', [integer(bytes, 6, 2)]],
      ['arp.src.hw', [integer(bytes, 8, 6)]],
      ['arp.src.ip', [integer(bytes, 14, 4)]],
      ['arp.dst.hw', [integer(bytes, 18, 6)]],
      ['arp.dst.ip', [integer(bytes, 24, 4)]],
    ]),
    payload: [],
  };
}
export function ip(bytes: number[]): Dissection {
  if (bytes.length < 20) throw new Malformed('ip: truncated header');
  const version = Math.floor(bytes[0] / 16);
  if (version !== 4) throw new Malformed(`ip: bad version ${version}`);
  const header = (bytes[0] % 16) * 4;
  if (header < 20) throw new Malformed(`ip: bad header length ${header}`);
  if (bytes.length < header) throw new Malformed('ip: truncated header');
  const total = integer(bytes, 2, 2);
  if (total < header) throw new Malformed(`ip: bad total length ${total}`);
  if (total > bytes.length) {
    throw new Malformed(`ip: truncated (total length ${total}, available ${bytes.length})`);
  }
  const flags = integer(bytes, 6, 2);
  const fields: Fields = new Map<string, FieldValue[]>([
    ['ip.hdr_len', [header]],
    ['ip.tos', [bytes[1]]],
    ['ip.len', [total]],
    ['ip.id', [integer(bytes, 4, 2)]],
    ['ip.flags.df', [bit(flags, 14)]],
    ['ip.flags.mf', [bit(flags, 13)]],
    ['ip.frag_offset', [(flags % 8192) * 8]],
    ['ip.ttl', [bytes[8]]],
    ['ip.proto', [bytes[9]]],
    ['ip.checksum', [integer(bytes, 10, 2)]],
    ['ip.checksum.status', [checksum(bytes.slice(0, header))]],
    ['ip.src', [integer(bytes, 12, 4)]],
    ['ip.dst', [integer(bytes, 16, 4)]],
  ]);
  if (bit(flags, 13) || flags % 8192) fields.set('ip.fragment', [true]);
  return { fields, payload: bytes.slice(header, total) };
}

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dns, rcodeName, typeName, type DnsAnswer } from './dns_app.ts';
import { aggregate, endpointNotation, marks, trackTcp } from './flows.ts';
import { dumpLines, readCapture, type Capture } from './hexdump.ts';
import {
  arp,
  bit,
  ethernet,
  hex,
  ip,
  ipv4,
  mac,
  Malformed,
  numeric,
  stringField,
  type Dissection,
  type Fields,
  type FieldValue,
} from './link_network.ts';
import { flagNames, icmp, tcp, udp } from './transport.ts';

